// One security-header policy for every response.
//
// Cloudflare applies public/_headers to static assets only: "Custom headers defined in the
// _headers file are not applied to responses generated by your Worker code." So every
// `prerender = false` route (story reader, forum threads, profiles…) shipped with no CSP at all.
// src/middleware.js now sets these on Worker responses; public/_headers keeps covering the
// prerendered pages. securityHeaders.test.js fails if the two ever disagree.
//
// script-src keeps 'unsafe-inline' on purpose: Astro hydrates islands with inline module
// scripts (see standing-decisions, CSP outage 2026-09-06).

export function buildCsp({ supabaseUrl, transcribeUrl } = {}) {
  const supabase = supabaseUrl ? [supabaseUrl, supabaseUrl.replace(/^http/, 'ws')] : []
  const connect = ["'self'", ...supabase, ...(transcribeUrl ? [transcribeUrl] : [])]
  const img = ["'self'", 'data:', ...(supabaseUrl ? [supabaseUrl] : [])]
  return [
    "default-src 'self'",
    "script-src 'self' 'unsafe-inline' https://static.cloudflareinsights.com",
    "style-src 'self' 'unsafe-inline'",
    "font-src 'self'",
    `connect-src ${connect.join(' ')}`,
    `img-src ${img.join(' ')}`,
    "object-src 'none'",
    "base-uri 'self'",
    "frame-ancestors 'none'",
    "form-action 'self'",
  ].join('; ') + ';'
}

export function securityHeaders(urls) {
  return {
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload',
    'X-Frame-Options': 'DENY',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    // microphone must stay (self): Dictate dies silently without it.
    'Permissions-Policy': 'geolocation=(), camera=(), microphone=(self)',
    'Content-Security-Policy': buildCsp(urls),
  }
}

// Sets any header the response doesn't already carry. Responses from fetch() or
// Response.redirect() have immutable headers, so fall back to a copy.
export function withSecurityHeaders(response, urls) {
  const headers = securityHeaders(urls)
  try {
    for (const [k, v] of Object.entries(headers)) if (!response.headers.has(k)) response.headers.set(k, v)
    return response
  } catch {
    const copy = new Response(response.body, response)
    for (const [k, v] of Object.entries(headers)) if (!copy.headers.has(k)) copy.headers.set(k, v)
    return copy
  }
}
